    pub(crate) fn compare_sd_client_config(
        &self,
        other: &Document,
        a: &SdClientConfig,
        b: &SdClientConfig,
        path: &str,
    ) -> Result<(), String> {
        Self::compare_ar_object(a.base(), b.base(), path)?;
        let list_a = a.get_capability_records();
        let list_b = b.get_capability_records();
        if list_a.len() != list_b.len() {
            return Err(format!("{path}: CAPABILITY_RECORDS length mismatch"));
        }
        for (index, (x, y)) in list_a.iter().zip(list_b.iter()).enumerate() {
            let x = self.tag_with_optional_values.get(*x).ok_or_else(|| {
                format!("{path}.CAPABILITY_RECORDS[{index}]: id not found in own arena")
            })?;
            let y = other.tag_with_optional_values.get(*y).ok_or_else(|| {
                format!("{path}.CAPABILITY_RECORDS[{index}]: id not found in other arena")
            })?;
            self.compare_tag_with_optional_value(
                other,
                x,
                y,
                &format!("{path}.CAPABILITY_RECORDS[{index}]"),
            )?;
        }
        if a.get_client_service_major_version() != b.get_client_service_major_version() {
            return Err(format!("{path}: CLIENT_SERVICE_MAJOR_VERSION mismatch"));
        }
        if a.get_client_service_minor_version() != b.get_client_service_minor_version() {
            return Err(format!("{path}: CLIENT_SERVICE_MINOR_VERSION mismatch"));
        }
        if a.get_initial_find_behavior() != b.get_initial_find_behavior() {
            return Err(format!("{path}: INITIAL_FIND_BEHAVIOR mismatch"));
        }
        if a.get_request_response_delay() != b.get_request_response_delay() {
            return Err(format!("{path}: REQUEST_RESPONSE_DELAY mismatch"));
        }
        if a.get_ttl() != b.get_ttl() {
            return Err(format!("{path}: TTL mismatch"));
        }
        Ok(())
    }

